	scwin.gridView1_ongroupby = function(options) {
				options.groupbyHeader = [{ inputType: 'expression', expression: 'toggle() + depthStr() + "    [ " + count() + " Cases ]  "', align: 'left', colSpan:4 }];								options.closeGroup = true,
				options.groupbyFooter = {
				depth_0 : [ {colSpan:3, value: "(1) Maximum Value", align: "right"}, { inputType: 'expression', expression:'MAX("col4")'} ],
				depth_1: [ {colSpan:3, value: "(2) Maximum Value", align: "right"}, { inputType: 'expression', expression:'MAX("col4")'} ],
				depth_2: [ {colSpan:3, value: "(3) Maximum Value", align: "right"}, { inputType: 'expression', expression:'MAX("col4")'} ]
				};								
				gridView1.groupby(options);

	};

scwin.gridView1_oncellclick = function(row,col,colId) {
	console.log(row, "click")
	window.row_click = row;
};

scwin.gridView1_oncontextopen = function(rowIndex,colIndex,focusedCell,info) {
	console.log(rowIndex, "oncontextopen")
	window.rowIndex_oncontextopen = rowIndex;
};

scwin.gridView1_onrightbuttonclick = function(row,col) {
 console.log(row, "rightbtn")
 window.row_rightbtn = row;
};

	scwin.fireClick = function(node){            
		if( document.createEventObject ) {
			node.fireEvent('oncontextmenu') ;  
		} else if( document.createEvent ) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('contextmenu', true, false);
			node.dispatchEvent(evt);    
		} else if (typeof node.contextmenu == 'function' ) {
			node.oncontextmenu();  
		}
	}
	scwin.rightClick = function(id){
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireClick(el);
	}        

			scwin.simulateWrapper = function(target, type, options) {
				WebSquare.wUnit.getJq(target).simulate(type, options);
			}
			scwin.setSimulate = function() {
				scwin.simulateWrapper('#gridView1_column4', 'drag-n-drop', {
					dx: 0,
					dy: -60
				});
			}

			scwin.checkVal2 = function() {
				return window.row_click == 1;
			}
			scwin.checkVal3 = function() {
				const check1 = window.rowIndex_oncontextopen == 1;
				const check2 = window.row_rightbtn == 1;
				return check1 && check2;
			}
			scwin.unitTest = function() {
				//Unit
				WebSquare.wUnit.start();
				WebSquare.wUnit.addCommand("pause", "500");
				WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column4').click()");
				WebSquare.wUnit.addCommand("pause", "400");
				WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
				WebSquare.wUnit.addCommand("pause", "500");
				WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
				WebSquare.wUnit.addCommand("pause", "400");
				WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_2_0').click()");
				WebSquare.wUnit.addCommand("pause", "400");
				WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
				WebSquare.wUnit.addCommand("pause", "500");	

				WebSquare.wUnit.addCommand("set", "scwin.rightClick('gridView1_cell_2_0')");
				WebSquare.wUnit.addCommand("pause", "400");
				WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()","true");
				WebSquare.wUnit.addCommand("pause", "500");				

				//Run test and stop
				WebSquare.wUnit.run();
				WebSquare.wUnit.stop();
			}	
			scwin.unitTest()
